mapper.select:
select v.version_id
from practice_preset_scene_versions v
join practice_activities a on a.id = v.activity_id
where a.slug = #{presetSceneId}
  and v.version = #{sourceVersion}
  and v.state = 'published'

mapper.update:
update practice_activities
set current_published_version_id = #{versionId}
where id = #{activityId}
